// Graceful stop: saves the world over RCON (the server's shutdown service: "saveworld"), asks the server to shut down
// ("ShutDownServer") and waits until it exits. Only the server process of THIS service is watched. When RCON does
// not answer (the server is still starting), the panel stops the process.
// Source RCON client (blocking socket calls with timeouts; async local functions do not work in panel scripts).
// Replies are read by arrival: the first packet, then whatever follows within a short gap.
byte[] RconPacket(int id, int type, string body)
{
    var payload = System.Text.Encoding.UTF8.GetBytes(body ?? string.Empty);
    var packet = new byte[14 + payload.Length];
    BitConverter.GetBytes(10 + payload.Length).CopyTo(packet, 0);
    BitConverter.GetBytes(id).CopyTo(packet, 4);
    BitConverter.GetBytes(type).CopyTo(packet, 8);
    payload.CopyTo(packet, 12);
    return packet;
}

bool RconReadExactly(System.Net.Sockets.NetworkStream stream, byte[] buffer, int count)
{
    var read = 0;
    while (read < count)
    {
        var n = stream.Read(buffer, read, count - read);
        if (n <= 0) return false;
        read += n;
    }
    return true;
}

// One packet (id, type, body) or null when nothing arrives within the socket's receive timeout.
Tuple<int, int, string> RconRead(System.Net.Sockets.TcpClient client)
{
    try
    {
        var stream = client.GetStream();
        var header = new byte[4];
        if (!RconReadExactly(stream, header, 4)) return null;
        var size = BitConverter.ToInt32(header, 0);
        if (size < 10 || size > 1 << 20) throw new Exception("Invalid RCON packet size " + size + ".");
        var data = new byte[size];
        if (!RconReadExactly(stream, data, size)) return null;
        var id = BitConverter.ToInt32(data, 0);
        var type = BitConverter.ToInt32(data, 4);
        var body = System.Text.Encoding.UTF8.GetString(data, 8, size - 10);
        return Tuple.Create(id, type, body);
    }
    catch (System.IO.IOException) { return null; } // receive timeout
}

// Connects and authenticates; throws with a readable message on failure.
System.Net.Sockets.TcpClient RconConnect(string host, int port, string password, int timeoutMs)
{
    var client = new System.Net.Sockets.TcpClient();
    if (!client.ConnectAsync(host, port).Wait(timeoutMs)) { client.Dispose(); throw new Exception("RCON " + host + ":" + port + " did not answer."); }
    client.ReceiveTimeout = timeoutMs; client.SendTimeout = timeoutMs;
    var auth = RconPacket(7, 3, password);
    client.GetStream().Write(auth, 0, auth.Length);
    while (true)
    {
        var packet = RconRead(client);
        if (packet == null) { client.Dispose(); throw new Exception("RCON login timed out."); }
        if (packet.Item2 != 2) continue; // an empty response value comes before the auth response
        if (packet.Item1 == -1) { client.Dispose(); throw new Exception("RCON refused the password."); }
        return client;
    }
}

// Sends one command and returns its reply ("" when the server sends none within firstMs).
string RconCommand(System.Net.Sockets.TcpClient client, string command, int firstMs)
{
    var packet = RconPacket(9, 2, command);
    client.GetStream().Write(packet, 0, packet.Length);
    var reply = new System.Text.StringBuilder();
    client.ReceiveTimeout = firstMs;
    var first = RconRead(client);
    if (first == null) return string.Empty;
    reply.Append(first.Item3);
    client.ReceiveTimeout = 400;
    while (true)
    {
        var next = RconRead(client);
        if (next == null) break;
        reply.Append(next.Item3);
    }
    return reply.ToString().Replace("\0", string.Empty).TrimEnd();
}


const int maxWaitSeconds = 120;
const string binary = "MOEServer";
var root = Path.GetFullPath((string)ThisService.RootDirectory).TrimEnd('/', '\\') + Path.DirectorySeparatorChar;

List<int> ServerPids()
{
    var pids = new List<int>();
    if (System.OperatingSystem.IsWindows())
    {
        foreach (var p in Process.GetProcessesByName(binary))
        {
            try { if (p.MainModule.FileName.StartsWith(root, StringComparison.OrdinalIgnoreCase)) pids.Add(p.Id); }
            catch { } // exited meanwhile
        }
        return pids;
    }
    foreach (var dir in Directory.EnumerateDirectories("/proc"))
    {
        if (!int.TryParse(Path.GetFileName(dir), out var pid)) continue;
        try
        {
            var args = File.ReadAllText(Path.Combine(dir, "cmdline")).Replace('\0', ' ').Replace('\\', '/');
            var target = new FileInfo(Path.Combine(dir, "exe")).LinkTarget ?? string.Empty;
            if ((target.StartsWith(root, StringComparison.Ordinal) && Path.GetFileName(target) == binary)
                || (args.Contains(binary + ".exe", StringComparison.OrdinalIgnoreCase) && args.Contains(root.Replace('\\', '/'), StringComparison.Ordinal)
                    && !args.Contains("start.exe", StringComparison.OrdinalIgnoreCase)))
                pids.Add(pid);
        }
        catch { } // gone meanwhile, or not ours to read
    }
    return pids;
}

var targets = ServerPids();
if (targets.Count == 0)
{
    ScriptConsole.WriteLine((object)"The server is not running.");
    return;
}

