using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text.RegularExpressions;
using System.Threading.Tasks;
using TCAdmin.Web.Shared.Models;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Myth of Empires loads the mod folders listed in -SteamModList="Mods/<id>+Mods/<id>" (paths relative to
// MOE/Binaries/Win64). Move the Workshop download to MOE/Binaries/Win64/Mods/<id>, add it to the Workshop mods
// variable and re-derive the command line; the server loads it the next time it starts.
string fileId = Convert.ToString(Dynamic.FileId).Trim();
if (!Regex.IsMatch(fileId, "^[0-9]+$")) throw new Exception("Unexpected Workshop id: " + fileId);
string installPath = Convert.ToString(Dynamic.InstallPath);
string root = (string)ThisService.RootDirectory;
string modsDir = Path.Combine(root, "MOE", "Binaries", "Win64", "Mods");
string target = Path.Combine(modsDir, fileId);

if (!string.IsNullOrEmpty(installPath) && Directory.Exists(installPath)
    && !string.Equals(Path.GetFullPath(installPath).TrimEnd('/', '\\'), Path.GetFullPath(target).TrimEnd('/', '\\'), StringComparison.OrdinalIgnoreCase))
{
    Directory.CreateDirectory(modsDir);
    try { if (Directory.Exists(target)) Directory.Delete(target, true); }
    catch (IOException) { throw new Exception("The running server uses the old copy of this mod: stop the server and install it again."); }
    Directory.Move(installPath, target);
    if (System.OperatingSystem.IsLinux())
    {
        Globals.OperatingSystem.SetFileOwnerAutoDetect(modsDir);
        foreach (var p in Directory.EnumerateFileSystemEntries(target, "*", SearchOption.AllDirectories).Prepend(target))
            Globals.OperatingSystem.SetFileOwnerAutoDetect(p);
    }
    ScriptConsole.WriteLine((object)("Moved the mod to MOE/Binaries/Win64/Mods/" + fileId + "."));
}
if (!Directory.Exists(target))
{
    ScriptConsole.WriteLine((object)("Nothing was downloaded for Workshop item " + fileId + "."));
    return;
}

// A folder still waiting to be removed (uninstalled while the server ran) is this new copy now: keep it.
string pending = Path.Combine(modsDir, ".pending-delete.txt");
if (File.Exists(pending)) File.WriteAllLines(pending, File.ReadAllLines(pending).Where(l => l.Trim() != fileId));

string entry = "Mods/" + fileId;
var service = await GameServiceManager.GetAsync(ThisService.ServiceId);
var current = service.Variables ?? new TCAdminVars();
var mods = current.Parse<string>("Mods", string.Empty)
    .Split(new[] { '+' }, StringSplitOptions.RemoveEmptyEntries)
    .Select(x => x.Trim()).Where(x => x.Length > 0).ToList();

if (mods.Contains(entry)) ScriptConsole.WriteLine((object)$"Workshop item {fileId} is already in the mod list.");
else mods.Add(entry);

// Mods has "Sync value with all commandlines" on: this writes the list into every saved command line (a saved
// predefined or custom line keeps its own copy of the variables) and the service variable, then refreshes the
// active command line.
string value = string.Join("+", mods);
await ServiceManager.SyncCommandlineVariables(ThisService.Owner, ThisService, new TCAdminVars { ["Mods"] = value });
ScriptConsole.WriteLine((object)("Workshop mods: " + value));
ScriptConsole.WriteLine((object)"Command line updated.");
ScriptConsole.WriteLine((object)"The mod is loaded the next time the server starts.");

