using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text.RegularExpressions;
using System.Threading.Tasks;
using TCAdmin.Web.Shared.Models;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Removes Mods/<id> from the Workshop mods variable (-SteamModList), re-derives the command line and deletes the
// mod folder MOE/Binaries/Win64/Mods/<id>. The change applies the next time the server starts.
string fileId = Convert.ToString(Dynamic.FileId).Trim();
if (!Regex.IsMatch(fileId, "^[0-9]+$")) throw new Exception("Unexpected Workshop id: " + fileId);
string entry = "Mods/" + fileId;

var service = await GameServiceManager.GetAsync(ThisService.ServiceId);
var current = service.Variables ?? new TCAdminVars();
var mods = current.Parse<string>("Mods", string.Empty)
    .Split(new[] { '+' }, StringSplitOptions.RemoveEmptyEntries)
    .Select(x => x.Trim()).Where(x => x.Length > 0).ToList();

if (mods.RemoveAll(m => m.Replace('\\', '/').TrimEnd('/') == entry) == 0)
    ScriptConsole.WriteLine((object)$"Workshop item {fileId} is not in the mod list.");

// Mods has "Sync value with all commandlines" on: this writes the list into every saved command line (a saved
// predefined or custom line keeps its own copy of the variables) and the service variable, then refreshes the
// active command line.
string value = string.Join("+", mods);
await ServiceManager.SyncCommandlineVariables(ThisService.Owner, ThisService, new TCAdminVars { ["Mods"] = value });
ScriptConsole.WriteLine((object)("Workshop mods: " + (mods.Count > 0 ? value : "(none)")));

string dir = Path.Combine((string)ThisService.RootDirectory, "MOE", "Binaries", "Win64", "Mods", fileId);
try { if (Directory.Exists(dir)) { Directory.Delete(dir, true); ScriptConsole.WriteLine((object)("Removed MOE/Binaries/Win64/Mods/" + fileId + ".")); } }
catch (Exception)
{
    // The running server keeps the mod's pak files open: the "Prepare the server" script removes the folder at the next start.
    File.AppendAllLines(Path.Combine(Path.GetDirectoryName(dir), ".pending-delete.txt"), new[] { fileId });
    ScriptConsole.WriteLine((object)("The running server uses MOE/Binaries/Win64/Mods/" + fileId + "; it is removed at the next start."));
}

ScriptConsole.WriteLine((object)"Command line updated.");
ScriptConsole.WriteLine((object)"The mod is no longer loaded from the next server start.");

